<?php
namespace App\Http\Controllers; use App\Models\DailyBalance; use App\Models\Transaction; use Illuminate\Http\Request;
class DashboardController extends Controller { public function __invoke(Request $request){$from=match($request->get('period','month')){'today'=>today(),'week'=>today()->subDays(6),default=>today()->startOfMonth()};$tx=Transaction::with('creator')->whereBetween('transaction_date',[$from,today()])->latest('transaction_date')->latest('id')->get();$sum=fn($type)=>(float)$tx->where('type',$type)->sum('amount');$balance=DailyBalance::where('balance_date',today())->first();$opening=(float)($balance?->opening_balance??0);$movement=$sum('sale')+$sum('transfer_in')-$sum('expense')-$sum('transfer_out');return view('dashboard',compact('tx','sum','balance','opening','movement','from'));} }
